  try {
    checkSsl();
    checkRealm();
    checkClient();
    checkResponseType();
    checkRedirectUri();
    createClientSession();
  } catch (ErrorPageException e) {
    return Response.status(Response.Status.BAD_REQUEST).entity(e.getMessage()).build();
